'use client';

import { useState, useEffect } from 'react';
import { User, Mail, Phone, MapPin, Shield, LogOut, Edit3, Check, X, Layers } from 'lucide-react';
import { useAppStore } from '@/lib/store';

export default function ProfilePage() {
  const { auth, navigate, logout, fetchMe } = useAppStore();
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(auth.user?.name || '');
  const [email, setEmail] = useState(auth.user?.email || '');
  const [phone, setPhone] = useState(auth.user?.phone || '');

  useEffect(() => { fetchMe(); }, [fetchMe]);

  if (!auth.isAuthenticated) {
    return (
      <div className="min-h-screen bg-hobbyco-cream flex items-center justify-center px-4 relative overflow-hidden">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute top-0 right-0 w-96 h-96 bg-hobbyco-green/5 rounded-full -translate-y-1/2 translate-x-1/3"></div>
          <div className="absolute bottom-0 left-0 w-72 h-72 bg-hobbyco-orange/5 rounded-full translate-y-1/2 -translate-x-1/3"></div>
        </div>
        
        <div className="text-center relative z-10">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Shield className="w-10 h-10 text-gray-300" />
          </div>
          <h2 className="text-xl font-black text-hobbyco-dark font-display mb-2">Please Sign In</h2>
          <p className="text-gray-500 mb-6 font-medium">You need to login to view your profile</p>
          <button onClick={() => navigate('login')} className="bg-hobbyco-orange text-white font-bold px-8 py-3 rounded-xl hover:bg-hobbyco-orange-dark transition-colors btn-hover-lift shadow-orange-glow">
            Sign In
          </button>
        </div>
      </div>
    );
  }

  const user = auth.user;

  return (
    <div className="min-h-screen bg-hobbyco-cream">
      <div className="max-w-2xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-24 h-24 bg-gradient-to-br from-hobbyco-orange to-hobbyco-orange-light rounded-full flex items-center justify-center mx-auto mb-4 shadow-orange-glow animate-float">
            <User className="w-12 h-12 text-white" />
          </div>
          <h1 className="text-2xl font-black text-hobbyco-dark font-display">{user?.name}</h1>
          <p className="text-gray-500 text-sm mt-1 font-medium">My Profile</p>
        </div>

        {/* Info Card */}
        <div className="bg-white rounded-2xl border border-gray-100 p-6 space-y-4 shadow-sm">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-hobbyco-dark font-display">Account Info</h2>
            <button
              onClick={() => setEditing(!editing)}
              className="text-sm text-hobbyco-orange font-bold flex items-center gap-1 hover:underline"
            >
              {editing ? <><X className="w-4 h-4" /> Cancel</> : <><Edit3 className="w-4 h-4" /> Edit</>}
            </button>
          </div>

          {/* Name */}
          <div className="flex items-center gap-3 py-2">
            <User className="w-5 h-5 text-gray-400 shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-400">Name</p>
              {editing ? (
                <input
                  value={name}
                  onChange={e => setName(e.target.value)}
                  className="w-full text-sm font-bold text-hobbyco-dark border-b border-gray-200 focus:outline-none focus:border-hobbyco-orange py-1"
                />
              ) : (
                <p className="text-sm font-bold text-hobbyco-dark">{user?.name}</p>
              )}
            </div>
          </div>

          {/* Email */}
          <div className="flex items-center gap-3 py-2">
            <Mail className="w-5 h-5 text-gray-400 shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-400">Email</p>
              {editing ? (
                <input
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  className="w-full text-sm font-bold text-hobbyco-dark border-b border-gray-200 focus:outline-none focus:border-hobbyco-orange py-1"
                />
              ) : (
                <p className="text-sm font-bold text-hobbyco-dark">{user?.email || '-'}</p>
              )}
            </div>
          </div>

          {/* Phone */}
          <div className="flex items-center gap-3 py-2">
            <Phone className="w-5 h-5 text-gray-400 shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-400">Phone</p>
              {editing ? (
                <input
                  value={phone}
                  onChange={e => setPhone(e.target.value)}
                  className="w-full text-sm font-bold text-hobbyco-dark border-b border-gray-200 focus:outline-none focus:border-hobbyco-orange py-1"
                />
              ) : (
                <p className="text-sm font-bold text-hobbyco-dark">{user?.phone || '-'}</p>
              )}
            </div>
          </div>

          {editing && (
            <button className="w-full bg-hobbyco-orange text-white font-black py-3 rounded-xl hover:bg-hobbyco-orange-dark transition-colors btn-hover-lift flex items-center justify-center gap-2">
              <Check className="w-4 h-4" /> Save Changes
            </button>
          )}
        </div>

        {/* Quick Actions */}
        <div className="bg-white rounded-2xl border border-gray-100 p-6 mt-4 space-y-3 shadow-sm">
          <h2 className="text-lg font-black text-hobbyco-dark font-display">Quick Actions</h2>
          <button
            onClick={() => navigate('my-collection')}
            className="w-full bg-hobbyco-green text-white font-black py-3 rounded-xl hover:bg-hobbyco-green-light transition-colors btn-hover-lift flex items-center justify-center gap-2"
          >
            <Layers className="w-4 h-4" /> My Collection
          </button>
        </div>

        {/* Logout */}
        <button
          onClick={async () => { await logout(); navigate('home'); }}
          className="w-full mt-4 bg-white border border-red-200 text-red-600 font-bold py-3 rounded-xl hover:bg-red-50 transition-colors flex items-center justify-center gap-2"
        >
          <LogOut className="w-4 h-4" /> Sign Out
        </button>
      </div>
    </div>
  );
}
